import { AnimatedIconFrame, type AnimatedIconProps } from "../icon-frame";
import "./bell.css";

type Props = AnimatedIconProps & {
  hasNotification?: boolean;
};

export function AnimatedBellIcon({ hasNotification = false, ...props }: Props) {
  return (
    <AnimatedIconFrame name="bell" data-notification={hasNotification ? "" : undefined} {...props}>
      <path
        data-part="body"
        d="M19.231 18H4.77a1.769 1.769 0 0 1-1.25-3.02l.602-.603A3 3 0 0 0 5 12.256V9.5a7 7 0 0 1 14 0v2.756a3 3 0 0 0 .879 2.121l.603.603a1.77 1.77 0 0 1-1.25 3.02"
      />
      <path data-part="clapper" d="M15.5 18a3.5 3.5 0 1 1-7 0" />
      {hasNotification ? <circle data-part="dot" cx="18.5" cy="5.5" r="3" /> : null}
    </AnimatedIconFrame>
  );
}

.animated-icon[data-icon="bell"] [data-part="dot"] {
  fill: var(--icon-badge, currentColor);
  stroke: var(--icon-badge-ring, transparent);
  stroke-width: 2;
  paint-order: stroke;
}

:is([data-icon-hover] .animated-icon, .animated-icon[data-icon-hover], .animated-icon[data-play]) {
  &[data-icon="bell"] {
    & [data-part="body"],
    & [data-part="clapper"] {
      transform-origin: 12px 2.5px;
      animation-duration: var(--icon-duration-long);
    }

    & [data-part="body"] {
      animation-name: icon-bell-body;
    }

    & [data-part="clapper"] {
      --icon-delay: 60ms;
      animation-name: icon-bell-clapper;
    }

    & [data-part="dot"] {
      --icon-scale: 0.6;
      --icon-overshoot: 0.8;
      --icon-delay: 120ms;
      transform-origin: 18.5px 5.5px;
      animation-name: icon-pop;
      animation-duration: var(--icon-duration-short);
    }
  }
}

@keyframes icon-bell-body {
  15% {
    transform: rotate(14deg);
  }
  35% {
    transform: rotate(-11deg);
  }
  55% {
    transform: rotate(7deg);
  }
  75% {
    transform: rotate(-3deg);
  }
}

@keyframes icon-bell-clapper {
  18% {
    transform: rotate(8deg) translateX(-2px);
  }
  38% {
    transform: rotate(-7deg) translateX(2.5px);
  }
  58% {
    transform: rotate(4deg) translateX(-1.5px);
  }
  78% {
    transform: rotate(-2deg) translateX(0.6px);
  }
}
